<template><view class="page"><view class="card form"><picker :range="reasons" @change="reasonType=reasons[Number($event.detail.value)]"><view>原因：{{ reasonType }}</view></picker><textarea v-model="description" placeholder="请说明具体问题" /><button @click="chooseProofs">选择凭证图片（{{ proofUrls.length }}）</button><button class="primary" @click="submit">提交申请</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{createAfterSale}from'@/api/customer';import{uploadFile}from'@/services/http';import{requireLogin}from'@/utils/auth-guard';const id=ref(0),reasons=['SERVICE_ISSUE','QUALITY_ISSUE','OTHER'],reasonType=ref(reasons[0]),description=ref(''),proofUrls=ref<string[]>([]);onLoad(q=>{if(!requireLogin('登录后才能申请售后'))return;id.value=Number(q?.id)});async function chooseProofs(){const picked=await uni.chooseImage({count:9-proofUrls.value.length});uni.showLoading({title:'上传中'});try{for(const path of picked.tempFilePaths)proofUrls.value.push(await uploadFile(path))}finally{uni.hideLoading()}}async function submit(){if(!description.value)return uni.showToast({title:'请填写问题说明',icon:'none'});await createAfterSale(id.value,{reasonType:reasonType.value,description:description.value,proofUrls:proofUrls.value});uni.showToast({title:'提交成功'});setTimeout(()=>uni.navigateBack(),500)}</script>
<style scoped>.form{display:flex;flex-direction:column;gap:28rpx}.form textarea{width:100%;height:280rpx;background:#f6f7fa;padding:20rpx;box-sizing:border-box;border-radius:16rpx}</style>
